<?php
namespace App\Http\Controllers;
use App\Modules\Operations\Models\Shift; use App\Modules\Tasks\Models\{Checklist,ChecklistItem,Task}; use Illuminate\Database\Eloquent\Builder; use Illuminate\Http\Request;
class TasksController extends Controller { public function tasks(Request $r){$q=Task::query()->withCount('checklistItems')->when($r->filled('search'),fn(Builder $q)=>$q->where(fn(Builder $n)=>$n->where('name','like','%'.$r->string('search').'%')->orWhere('description','like','%'.$r->string('search').'%')))->when($r->filled('status'),fn(Builder $q)=>$q->where('status',$r->string('status')));return view('tenant.tasks.tasks',['tasks'=>$q->orderBy('name')->paginate(10)->withQueryString(),'summary'=>['total'=>Task::count(),'active'=>Task::where('status','active')->count(),'inactive'=>Task::where('status','inactive')->count(),'in_checklists'=>Task::has('checklistItems')->count()]]);} public function storeTask(Request $r){Task::create($r->validate(['name'=>'required|max:150','description'=>'nullable','status'=>'required|in:active,inactive']));return back();} public function checklists(Request $r){$q=Checklist::query()->with('shift')->withCount(['items','executions'])->when($r->filled('search'),fn(Builder $q)=>$q->where('name','like','%'.$r->string('search').'%'))->when($r->filled('status'),fn(Builder $q)=>$q->where('status',$r->string('status')))->when($r->filled('shift_id'),fn(Builder $q)=>$q->where('shift_id',$r->integer('shift_id')))->when($r->input('usage')==='used',fn(Builder $q)=>$q->has('executions'))->when($r->input('usage')==='unused',fn(Builder $q)=>$q->doesntHave('executions'));return view('tenant.tasks.checklists',['checklists'=>$q->orderBy('name')->paginate(10)->withQueryString(),'tasks'=>Task::where('status','active')->get(),'shifts'=>Shift::where('status','active')->orderBy('name')->get(),'summary'=>['total'=>Checklist::count(),'active'=>Checklist::where('status','active')->count(),'inactive'=>Checklist::where('status','inactive')->count(),'used'=>Checklist::has('executions')->count()]]);} public function storeChecklist(Request $r){Checklist::create($r->validate(['name'=>'required|max:150','shift_id'=>'required|exists:tenant.shifts,id','status'=>'required|in:active,inactive']));return back();} public function storeItem(Request $r, Checklist $checklist){$d=$r->validate(['task_id'=>'required|exists:tenant.tasks,id','sort_order'=>'required|integer|min:1','start_time'=>'nullable','due_time'=>'nullable']);$d['checklist_id']=$checklist->id;ChecklistItem::create($d);return back();} }
